sys_script_fix.script:
// TABLES
var RP_TABLE = 'x_kp101_kpmg_res_0_resource_profile';
var FLAT_TABLE = 'x_kp101_kpmg_res_0_resource_profile_summary';

var UC_TABLE = 'x_kp101_kpmg_res_0_user_certification';
var US_TABLE = 'x_kp101_kpmg_res_0_user_skill';
var UP_TABLE = 'x_kp101_kpmg_res_0_user_project_assignment';
var IE_TABLE = 'x_kp101_kpmg_res_0_industry_experience';

// FIELDS (FLAT TABLE)
var FLAT_RESOURCE_FIELD = 'resource';
var FLAT_RESOURCE_FIELD2 = 'user';
var FLAT_CERT_FIELD = 'certificates';
var FLAT_SKILL_FIELD = 'skills';
var FLAT_PROJECT_FIELD = 'projects';
var FLAT_SECTOR_FIELD = 'industry_experience';

// FIELDS (SOURCE TABLES)
var RESOURCE_FIELD = 'resource'; // consistent across your tables

// LOOP ALL RESOURCE PROFILES
var rp = new GlideRecord(RP_TABLE);
rp.query();

gs.info('Starting population...');

while (rp.next()) {

    // =====================
    // CERTIFICATES
    // =====================\

    var certs = [];
    var uc = new GlideRecord(UC_TABLE);
    uc.addQuery(RESOURCE_FIELD, rp.sys_id);
    uc.query();

    while (uc.next()) {
        if (uc.certificate) {
            certs.push(uc.certificate.toString());
        }
    }
    certs = Array.from(new Set(certs));

    // =====================
    // SKILLS
    // =====================
    var skills = [];
    var us = new GlideRecord(US_TABLE);
    us.addQuery('user', rp.sys_id);
    us.query();

    while (us.next()) {
        if (us.skill) {
            skills.push(us.skill.toString());
        }
    }
    skills = Array.from(new Set(skills));

    // =====================
    // PROJECTS
    // =====================
    var projects = [];
    var up = new GlideRecord(UP_TABLE);
    up.addQuery('user', rp.sys_id);
    up.query();

    while (up.next()) {
        if (up.project_assignment) {
            projects.push(up.project_assignment.toString());
        }
    }
    projects = Array.from(new Set(projects));

    // =====================
    // INDUSTRY EXPERIENCE (SECTORS)
    // =====================

    var sectors = [];
    var ie = new GlideRecord(IE_TABLE);
    ie.addQuery(RESOURCE_FIELD, rp.sys_id);
    ie.query();

    while (ie.next()) {
        if (ie.sector) {
            sectors.push(ie.sector.toString());
        }
    }
    sectors = Array.from(new Set(sectors));

    // =====================
    // FIND OR CREATE FLAT RECORD
    // =====================
    var flat = new GlideRecord(FLAT_TABLE);
    if (!flat.get(FLAT_RESOURCE_FIELD, rp.sys_id)) {
        flat.initialize();
        flat[FLAT_RESOURCE_FIELD] = rp.sys_id;
    }

    // =====================
    // SET GLIDE LIST FIELDS
    // =====================
    flat[FLAT_CERT_FIELD] = certs.join(',');
    flat[FLAT_SKILL_FIELD] = skills.join(',');
    flat[FLAT_PROJECT_FIELD] = projects.join(',');
    flat[FLAT_SECTOR_FIELD] = sectors.join(',');

    flat.update();

    gs.info('Processed RP: ' + rp.sys_id +
        ' | Certs: ' + certs.length +
        ' | Skills: ' + skills.length +
        ' | Projects: ' + projects.length +
        ' | Sectors: ' + sectors.length);
}

gs.info('Done.');
